from openai import OpenAI
from typing import Callable

client = OpenAI()

def stream_with_cb(prompt: str, on_token: Callable[[str], None]) -> str:
    out = []
    s = client.chat.completions.create(
        model="{{model_name}}",
        messages=[{"role": "user", "content": prompt}],
        stream=True,
    )
    for chunk in s:
        d = chunk.choices[0].delta.content
        if d:
            on_token(d)
            out.append(d)
    return "".join(out)

if __name__ == "__main__":
    full = stream_with_cb("hi", lambda t: print(t, end=""))
